insert into public.system_drugs(id,drug_data,sort_order) values ('ppi','{"id":"ppi","name":"PPI 制酸劑","subtypes":["Omeprazole 20mg","Esomeprazole 40mg","Lansoprazole 30mg","Rabeprazole 20mg","Pantoprazole 40mg"],"shape":"round","color":"#FFA726","color2":null,"note":""}'::jsonb,0) on conflict (id) do nothing;
