insert into public.system_drugs(id,drug_data,sort_order) values ('bismuth','{"id":"bismuth","name":"KCB 鉍劑","subtypes":["Bismuth Subcitrate 120mg"],"shape":"round","color":"#90A4AE","color2":null,"note":"大便及舌頭顏色可能暫時變黑灰色。"}'::jsonb,2) on conflict (id) do nothing;
insert into public.system_drugs(id,drug_data,sort_order) values ('amoxicillin','{"id":"amoxicillin","name":"Amoxicillin 抗生素","subtypes":["Amoxicillin 250mg","Amoxicillin 500mg"],"shape":"capsule","color":"#EF5350","color2":"#BDBDBD","note":"若對盤尼西林或青黴素類抗生素過敏，請主動告知醫師。"}'::jsonb,3) on conflict (id) do nothing;
insert into public.system_drugs(id,drug_data,sort_order) values ('clarithromycin','{"id":"clarithromycin","name":"Clarithromycin 抗生素","subtypes":["Clarithromycin 500mg"],"shape":"round","color":"#FFD740","color2":null,"note":"嘴巴會有金屬味或苦味。"}'::jsonb,4) on conflict (id) do nothing;
insert into public.system_drugs(id,drug_data,sort_order) values ('metronidazole','{"id":"metronidazole","name":"Metronidazole 抗生素","subtypes":["Metronidazole 250mg","Metronidazole 500mg"],"shape":"round","color":"#FF7043","color2":null,"note":"嘴巴會有金屬味。治療期間及停藥後 48–72 小時禁止飲酒。"}'::jsonb,5) on conflict (id) do nothing;
insert into public.system_drugs(id,drug_data,sort_order) values ('tetracycline','{"id":"tetracycline","name":"Tetracycline 抗生素","subtypes":["Tetracycline 500mg","Tetracycline 250mg"],"shape":"capsule","color":"#66BB6A","color2":"#E0E0E0","note":"服藥前後 2 小時避免牛奶及鈣片。外出加強防曬（光敏感）。"}'::jsonb,6) on conflict (id) do nothing;
insert into public.system_drugs(id,drug_data,sort_order) values ('levofloxacin','{"id":"levofloxacin","name":"Levofloxacin 抗生素","subtypes":["Levofloxacin 500mg"],"shape":"oval","color":"#80DEEA","color2":null,"note":"避免與鈣片、鐵劑同時服用。若出現腳跟痛或肌腱疼痛立即停藥並回診。"}'::jsonb,7) on conflict (id) do nothing;
insert into public.system_drugs(id,drug_data,sort_order) values ('rifabutin','{"id":"rifabutin","name":"Rifabutin 抗生素","subtypes":["Rifabutin 150mg"],"shape":"capsule","color":"#CE93D8","color2":"#9575CD","note":"尿液、汗液、眼淚會暫時變橘紅色。"}'::jsonb,8) on conflict (id) do nothing;
