insert into public.system_regimens(id,regimen_data,sort_order,name) values ('bqt','{"id":"bqt","name":"鉍劑四合一處方","isPhased":false,"duration":14,"notes":"1. 請按時服藥，切勿自行停藥，即使症狀改善也應完成整個療程。\n2. 如出現嚴重腸胃不適、嚴重過敏反應或其他異常，請立即回診。\n3. 治療結束後，請依醫師指示回診追蹤，確認幽門桿菌是否已根除。","phases":[{"drugs":[{"drugId":"ppi","subtype":3,"freq":2,"pills":1,"times":null,"customName":null,"icon":null},{"drugId":"bismuth","subtype":0,"freq":3,"pills":1,"times":null,"customName":null,"icon":null},{"drugId":"tetracycline","subtype":0,"freq":3,"pills":1,"times":null,"customName":null,"icon":null},{"drugId":"metronidazole","subtype":0,"freq":3,"pills":2,"times":null,"customName":null,"icon":null}]}]}'::jsonb,0,'鉍劑四合一處方') on conflict (id) do nothing;
